import io, flask, werkzeug
app = flask.Flask("demo")
app.secret_key = "k"
@app.route("/hello/<name>")
def hello(name):
    flask.session["n"] = name
    return flask.jsonify(msg="hi " + name, url=flask.url_for("hello", name="x"))
@app.route("/who")
def who():
    return flask.session.get("n", "none")
@app.route("/file")
def f():
    return flask.send_file(io.BytesIO(b"data"), mimetype="text/plain", download_name="a.txt")
@app.route("/go")
def go():
    return flask.redirect("/who")
@app.route("/post", methods=["POST"])
def post():
    return flask.jsonify(flask.request.get_json())
c = app.test_client()
r = c.get("/hello/bob"); assert r.status_code == 200, r.status
assert r.get_json() == {"msg": "hi bob", "url": "/hello/x"}, r.get_json()
assert c.get("/who").data == b"bob"
r = c.get("/file"); assert r.data == b"data" and "a.txt" in r.headers["Content-Disposition"]
r = c.get("/go", follow_redirects=True); assert r.data == b"bob", r.data
r = c.post("/post", json={"a": 1}); assert r.get_json() == {"a": 1}
assert c.get("/missing").status_code == 404
with app.test_request_context("/hello/z?q=1"):
    assert flask.request.args["q"] == "1"
print("OK", werkzeug.__version__)
